function DocumentsPageFixed(){
  const {user}=useAuth(); const [items,setItems]=useState(DOCUMENT_ROWS); const [params,setParams]=useSearchParams(); const [tab,setTab]=useState(params.get("status")==="action-required"?"Action Required":"All Documents"); const [property,setProperty]=useState("All Properties"); const [type,setType]=useState("All Document Types"); const [format,setFormat]=useState("All File Types"); const [showFilters,setShowFilters]=useState(false); const [selected,setSelected]=useState(null); const [showUpload,setShowUpload]=useState(false); const [uploading,setUploading]=useState(false); const [upload,setUpload]=useState({file:null,type:"Property Document",related:"Executive Office Space — Waigani"});
  const query=params.get("search")||""; const docs=items.filter(d=>(tab==="All Documents"||(tab==="Property Documents"&&d[7]==="Property")||(tab==="Identity Documents"&&d[7]==="Identity")||(tab==="Action Required"&&d[4]==="Action Required"))&&(property==="All Properties"||d[2]===property)&&(type==="All Document Types"||d[1]===type)&&(format==="All File Types"||d[3]===format)&&(!query||d.join(" ").toLowerCase().includes(query.toLowerCase())));
  const setQuery=value=>{const next=new URLSearchParams(params);if(value)next.set("search",value);else next.delete("search");setParams(next,{replace:true});};
  const openDocument=document=>{if(document[8]){window.open(document[8],"_blank","noopener,noreferrer");return;}toast.error("No file is attached to this document record");};
  const selectFile=file=>{if(!file){setUpload(current=>({...current,file:null}));return;}const allowed=["application/pdf","image/jpeg","image/png"];if(!allowed.includes(file.type)){toast.error("Use a PDF, JPG or PNG document");setUpload(current=>({...current,file:null}));return;}if(file.size<100){toast.error("Selected document is empty");setUpload(current=>({...current,file:null}));return;}if(file.size>10*1024*1024){toast.error("Document must not exceed 10 MB");setUpload(current=>({...current,file:null}));return;}setUpload(current=>({...current,file}));};
  const uploadDocument=async()=>{if(!upload.file||!upload.type||!upload.related)return;const body=new FormData();body.append("file",upload.file);setUploading(true);try{const {data}=await api.post("/documents/upload",body);const formatName=upload.file.name.split(".").pop().toUpperCase();const category=upload.type==="Identity Document"?"Identity":"Property";setItems(current=>[[upload.file.name,upload.type,upload.related,formatName,"Under Review",`${(upload.file.size/1024/1024).toFixed(1)} MB`,new Date().toLocaleDateString("en-GB"),category,data.url],...current]);setTab(category==="Identity"?"Identity Documents":"All Documents");setUpload({file:null,type:"Property Document",related:"Executive Office Space — Waigani"});setShowUpload(false);toast.success("Document uploaded for review");}catch(err){toast.error(formatError(err));}finally{setUploading(false);}};
  return <><PageHead title="Documents" sub="Upload and manage property and account documents." action={<Button onClick={()=>setShowUpload(true)}><Upload/> Upload Document</Button>}/><div className="adv-stat-grid four">{[[items.length,"All Documents"],[items.filter(x=>x[4]==="Verified").length,"Verified"],[items.filter(x=>x[4]==="Under Review").length,"Under Review"],[items.filter(x=>x[4]==="Action Required").length,"Action Required"]].map((x,i)=><Card className="adv-stat-number" key={x[1]}><b className={["blue","green","orange","red"][i]}>{x[0]}</b><span>{x[1]}</span></Card>)}</div><Card>
    <div className="adv-tabs">{["All Documents","Property Documents","Identity Documents","Action Required"].map(name=><button className={tab===name?"active":""} onClick={()=>setTab(name)} key={name}>{name}</button>)}</div><div className="adv-table-tools"><label><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search documents..."/></label><select aria-label="Filter by property" value={property} onChange={e=>setProperty(e.target.value)}>{["All Properties",...new Set(items.map(x=>x[2]))].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Filter by document type" value={type} onChange={e=>setType(e.target.value)}>{["All Document Types",...new Set(items.map(x=>x[1]))].map(x=><option key={x}>{x}</option>)}</select><Button secondary onClick={()=>setShowFilters(show=>!show)}><SlidersHorizontal/> Filters</Button></div>
    {showFilters&&<div className="adv-inline-filter"><label className="adv-field"><span>File type</span><select value={format} onChange={e=>setFormat(e.target.value)}><option>All File Types</option><option>PDF</option><option>JPG</option><option>PNG</option></select></label><Button secondary onClick={()=>{setProperty("All Properties");setType("All Document Types");setFormat("All File Types");}}>Clear filters</Button></div>}
    <div className="adv-table-wrap"><table><thead><tr><th>Document</th><th>Type</th><th>Related To</th><th>Uploaded</th><th>Status</th><th>Action</th></tr></thead><tbody>{docs.map(d=><tr key={`${d[0]}-${d[6]}`}><td><div className="adv-doc-cell"><FileText/><span><b>{d[0]}</b><small>{d[3]} • {d[5]}</small></span></div></td><td>{d[1]}</td><td>{d[2]}</td><td>{d[6]}<small>by {user?.name||"Property Advertiser"}</small></td><td><Status tone={d[4]==="Verified"?"green":d[4]==="Under Review"?"orange":"red"}>{d[4]}</Status></td><td><button aria-label={`Open document ${d[0]}`} onClick={()=>setSelected(d)}><MoreVertical/></button></td></tr>)}</tbody></table></div>{!docs.length&&<p className="adv-empty">No matching documents.</p>}</Card><div className="adv-note"><ShieldCheck/> Your documents are stored securely and only accessible to you and authorised TREL staff.</div>
    {selected&&<Modal title={selected[0]} onClose={()=>setSelected(null)}><p><b>Type:</b> {selected[1]}</p><p><b>Related to:</b> {selected[2]}</p><p><b>Uploaded:</b> {selected[6]}</p><Status tone={selected[4]==="Verified"?"green":"orange"}>{selected[4]}</Status><div className="adv-modal-actions"><Button disabled={!selected[8]} onClick={()=>openDocument(selected)}>View Document</Button><Button secondary onClick={()=>{setItems(current=>current.filter(item=>item!==selected));setSelected(null);toast.success("Document removed")}}>Remove</Button></div></Modal>}
    {showUpload&&<Modal title="Upload Document" onClose={()=>!uploading&&setShowUpload(false)}><label className="adv-field"><span>Document type *</span><select required value={upload.type} onChange={e=>{const next=e.target.value;setUpload(current=>({...current,type:next,related:next==="Identity Document"?"Account Verification":current.related}));}}><option>Property Ownership</option><option>Authority Document</option><option>Valuation Report</option><option>Identity Document</option><option>Property Document</option></select></label><label className="adv-field"><span>Related property or account *</span><select required value={upload.related} onChange={e=>setUpload(current=>({...current,related:e.target.value}))}><option>Account Verification</option>{[...new Set(properties.map(x=>x[0]))].map(x=><option key={x}>{x}</option>)}</select></label><label className="adv-field"><span>Select document *</span><input required type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" onChange={e=>selectFile(e.target.files?.[0]||null)}/><small>PDF, JPG or PNG • Maximum 10 MB</small></label><div className="adv-modal-actions"><Button disabled={uploading||!upload.file||!upload.type||!upload.related} onClick={uploadDocument}>{uploading?"Uploading…":"Upload"}</Button></div></Modal>}</>;
}

function AccountSettingsFixed(){
  const {user,updateUser}=useAuth(); const flow=useDraft(); const navigate=useNavigate(); const [settingsParams]=useSearchParams(); const returnToReview=settingsParams.get("return")==="property-review"; const [tab,setTab]=useState(settingsParams.get("section")==="identity"?"Identity Verification":"Profile Information"); const [saving,setSaving]=useState(false); const [profileLoaded,setProfileLoaded]=useState(false); const [identityDocs,setIdentityDocs]=useState([]); const [identity,setIdentity]=useState({document_type:"National Identification Card",file:null}); const [profile,setProfile]=useState({name:user?.name||"",phone:user?.phone||"",email:user?.email||"",preferred_communication:"WhatsApp",residential_address:"",business_name:"",ipa_registration_number:"",position:"",business_phone:"",profile_photo_url:"",notification_preferences:{email:true,whatsapp:true,sms:false}});
  useEffect(()=>{api.get("/auth/me").then(({data})=>{const p=data.advertiser_profile||{};setIdentityDocs(data.identity_documents||[]);setProfile(current=>({...current,name:data.name||"",phone:data.phone||"",email:data.email||"",preferred_communication:p.preferred_communication||"WhatsApp",residential_address:p.residential_address||"",business_name:p.business_name||"",ipa_registration_number:p.ipa_registration_number||"",position:p.position||"",business_phone:p.business_phone||"",profile_photo_url:p.profile_photo_url||"",notification_preferences:p.notification_preferences||current.notification_preferences}));}).catch(err=>toast.error(formatError(err))).finally(()=>setProfileLoaded(true));},[]);
  const phonePattern=/^\+?[0-9\s-]{5,40}$/; const change=(key,value)=>setProfile(current=>({...current,[key]:value}));
  const save=async(keys)=>{setSaving(true);try{const payload=Object.fromEntries(keys.map(key=>[key,profile[key]]));const {data}=await api.put("/auth/me",payload);updateUser({name:data.name,phone:data.phone});toast.success("Account settings saved");}catch(err){toast.error(formatError(err));}finally{setSaving(false);}};
  const profileValid=profile.name.trim().length>=2&&phonePattern.test(profile.phone)&&profile.residential_address.trim().length>0;
  const businessHasData=["business_name","ipa_registration_number","position","business_phone"].some(key=>String(profile[key]||"").trim()); const businessValid=businessHasData&&profile.business_name.trim().length>=2&&(!profile.business_phone||phonePattern.test(profile.business_phone));
  const changePhoto=async(event)=>{const selected=event.target.files?.[0];event.target.value="";if(!selected)return;if(!["image/jpeg","image/png","image/webp"].includes(selected.type)){toast.error("Use a JPG, PNG or WebP image");return;}if(selected.size<100){toast.error("Selected image is empty");return;}if(selected.size>5*1024*1024){toast.error("Profile photo must not exceed 5 MB");return;}const body=new FormData();body.append("file",selected);setSaving(true);try{const {data:uploaded}=await api.post("/public/upload",body);await api.put("/auth/me",{profile_photo_url:uploaded.url});change("profile_photo_url",uploaded.url);toast.success("Profile photo updated");}catch(err){toast.error(formatError(err));}finally{setSaving(false);}};
  const selectIdentityFile=file=>{if(!file){setIdentity(current=>({...current,file:null}));return;}if(!["application/pdf","image/jpeg","image/png"].includes(file.type)){toast.error("Use a PDF, JPG or PNG identity document");setIdentity(current=>({...current,file:null}));return;}if(file.size<100){toast.error("Selected identity document is empty");setIdentity(current=>({...current,file:null}));return;}if(file.size>10*1024*1024){toast.error("Identity document must not exceed 10 MB");setIdentity(current=>({...current,file:null}));return;}setIdentity(current=>({...current,file}));};
  const submitIdentity=async()=>{const file=identity.file;if(!file)return;const body=new FormData();const documentType={"National Identification Card":"NID_CARD","Driver Licence":"DRIVER_LICENCE","Passport":"PASSPORT"}[identity.document_type]||"NID_CARD";body.append("document_type",documentType);body.append("file",file);setSaving(true);try{const {data:document}=await api.post("/identity-documents/upload",body);setIdentityDocs(current=>[{...document,document_type:identity.document_type,file_name:file.name},...current]);setIdentity(current=>({...current,file:null}));toast.success("Identity document submitted for verification");}catch(err){toast.error(formatError(err));}finally{setSaving(false);}};
  const initials=(profile.name||"PA").split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase();
  const field=(label,key,type="text",pattern)=>{const invalid=pattern&&profile[key]&&!pattern.test(profile[key]);return <label className="adv-field"><span>{label}</span><input type={type} required={label.includes("*")} pattern={pattern?.source} aria-invalid={invalid||undefined} disabled={!profileLoaded||saving} value={profile[key]||""} onChange={e=>change(key,e.target.value)}/>{invalid&&<small>Enter a valid PNG contact number.</small>}</label>;};
  const verified=identityDocs.find(doc=>String(doc.status).toUpperCase()==="VERIFIED"); const latest=verified||identityDocs[0];
  return <><PageHead title="Account Settings" sub="Manage your profile, verification and preferences."/><div className="adv-settings-layout"><aside>{[["Profile Information",UserRound],["Identity Verification",ShieldCheck],["Business Details",Building2],["Notifications",Bell],["Security",Settings]].map(([name,Icon])=><button className={tab===name?"active":""} onClick={()=>setTab(name)} key={name}><Icon/> {name}</button>)}</aside><div>
    {tab==="Profile Information"&&<Card><h2>Profile Information</h2><p>Keep your personal and contact information up to date.</p><div className="adv-profile-row"><span>{profile.profile_photo_url?<img src={profile.profile_photo_url} alt="Profile" style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:"50%"}}/>:initials}</span><div><b>{profile.name||"Property Advertiser"}</b><small>Property Advertiser</small></div><label className="adv-button secondary">{saving?"Uploading…":"Change photo"}<input hidden disabled={!profileLoaded||saving} type="file" accept="image/jpeg,image/png,image/webp" onChange={changePhoto}/></label></div><div className="adv-form-grid two">{field("Full Name *","name")}{field("Mobile Number *","phone","tel",phonePattern)}<label className="adv-field"><span>Email Address</span><input value={profile.email} readOnly/></label><label className="adv-field"><span>Preferred Communication</span><select disabled={!profileLoaded||saving} value={profile.preferred_communication} onChange={e=>change("preferred_communication",e.target.value)}>{["WhatsApp","Email","Both"].map(x=><option key={x}>{x}</option>)}</select></label></div>{field("Residential Address *","residential_address")}<Button disabled={!profileLoaded||saving||!profileValid} onClick={()=>save(["name","phone","preferred_communication","residential_address"])}>Save Changes</Button>{!profileValid&&<p className="adv-muted">Full name, a valid contact number and residential address are required.</p>}</Card>}
    {tab==="Identity Verification"&&<Card><div className="adv-section-head"><div><h2>Identity Verification</h2><p>One valid government-issued ID is required.</p></div><Status tone={verified?"green":"orange"}>{verified?"Verified":latest?"Under Review":"Pending"}</Status></div>{latest&&<div className="adv-id-card"><FileCheck2/><div><b>{latest.document_type||"Government ID"}</b><small>{String(latest.status||"Pending").replace(/_/g," ")}</small><small>{latest.file_name||""}</small></div>{latest.url&&<a className="adv-button secondary" href={latest.url} target="_blank" rel="noreferrer">View Document</a>}</div>}<div className="adv-form-grid two"><label className="adv-field"><span>Legal ID type *</span><select required value={identity.document_type} onChange={e=>setIdentity(current=>({...current,document_type:e.target.value}))}><option>National Identification Card</option><option>Passport</option><option>Driver Licence</option></select></label><label className="adv-field"><span>Identity document *</span><input required type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" onChange={e=>{selectIdentityFile(e.target.files?.[0]||null);e.target.value="";}}/><small>PDF, JPG or PNG • Maximum 10 MB</small></label></div><div className="adv-form-footer"><Button disabled={saving||!identity.file} onClick={submitIdentity}>{saving?"Uploading…":"Submit for Verification"}</Button>{returnToReview&&flow.loaded&&flow.draft.title&&<Button secondary onClick={()=>navigate("/advertiser/add-property/review?resume=1")}>Return to Property Review</Button>}</div><p className="adv-muted">Accepted IDs include a passport, driver licence or National Identification Card.</p></Card>}
    {tab==="Business Details"&&<Card><h2>Business Details</h2><p>Required for authorised agents and business advertisers.</p><div className="adv-form-grid two">{field("Business / Agency Name","business_name")}{field("IPA Registration Number","ipa_registration_number")}{field("Position / Role","position")}{field("Business Phone","business_phone","tel",phonePattern)}</div><Button disabled={!profileLoaded||saving||!businessValid} onClick={()=>save(["business_name","ipa_registration_number","position","business_phone"])}>Save Business Details</Button>{!businessHasData&&<p className="adv-muted">Enter business information before saving.</p>}</Card>}
    {tab==="Notifications"&&<Card><h2>Notifications</h2><p>Choose how TRELPNG should contact you.</p>{[["email","Email notifications"],["whatsapp","WhatsApp notifications"],["sms","SMS notifications"]].map(([key,label])=><label className="adv-setting-check" key={key}><input type="checkbox" disabled={!profileLoaded||saving} checked={!!profile.notification_preferences[key]} onChange={e=>change("notification_preferences",{...profile.notification_preferences,[key]:e.target.checked})}/>{label}</label>)}<Button disabled={!profileLoaded||saving} onClick={()=>save(["notification_preferences"])}>Save Notification Preferences</Button></Card>}
    {tab==="Security"&&<Card><h2>Security</h2><p>Use the secure password-reset flow to change your password.</p><Link className="adv-button" to="/add-property?auth=forgot">Reset Password</Link></Card>}
  </div></div></>;
}

function ActivityPage(){const {currentStep}=useDraft();const continueDraftPath=`${DRAFT_ROUTES[currentStep-1]||DRAFT_ROUTES[0]}?resume=1`;return <><PageHead title="Recent Activity" sub="Open the enquiry, listing or draft connected to each update."/><Card className="adv-activity adv-activity-page">{RECENT_ACTIVITY.map((item,i)=>{const to=item[3]==="draft"?continueDraftPath:item[3];return <Link className="adv-activity-row" to={to} key={`${item[0]}-${i}`}><i className={`dot d${i}`}/><span><b>{item[0]}</b><small>{item[1]}</small></span><time>{item[2]}</time><ChevronRight size={15}/></Link>})}</Card></>}

function SearchResultsPage(){const [params]=useSearchParams();const query=(params.get("q")||"").trim();const needle=query.toLowerCase();const propertyResults=buildPropertyRows().filter((row)=>`${row.property[0]} ${row.property[1]} ${row.id}`.toLowerCase().includes(needle)).slice(0,5);const enquiryResults=ENQUIRY_ROWS.filter((row)=>row.join(" ").toLowerCase().includes(needle));const documentResults=DOCUMENT_ROWS.filter((row)=>row.join(" ").toLowerCase().includes(needle));const total=propertyResults.length+enquiryResults.length+documentResults.length;return <><PageHead title="Search Results" sub={query?`${total} result${total===1?"":"s"} for “${query}”`:"Enter a search from the dashboard header."}/><div className="adv-search-results">{propertyResults.length>0&&<Card><h3>Properties</h3>{propertyResults.map((row)=><Link to={`/advertiser/properties?property=${row.id}`} key={row.id}><House/><span><b>{row.property[0]}</b><small>{row.property[1]} • Property #{row.id}</small></span><ChevronRight/></Link>)}</Card>}{enquiryResults.length>0&&<Card><h3>Enquiries</h3>{enquiryResults.map((row)=><Link to={`/advertiser/enquiries?search=${encodeURIComponent(row[0])}`} key={row[0]}><MessageCircle/><span><b>{row[0]}</b><small>{row[1]} • {row[3]}</small></span><ChevronRight/></Link>)}</Card>}{documentResults.length>0&&<Card><h3>Documents</h3>{documentResults.map((row)=><Link to={`/advertiser/documents?search=${encodeURIComponent(row[0])}`} key={row[0]}><FileText/><span><b>{row[0]}</b><small>{row[1]} • {row[4]}</small></span><ChevronRight/></Link>)}</Card>}{query&&!total&&<Card className="adv-empty">No properties, enquiries or documents match “{query}”.</Card>}</div></>}

function HelpPage(){return <><PageHead title="Help Centre" sub="Find answers, guides and support for your property advertising workspace."/><Card className="adv-help-hero"><CircleHelp/><h2>How can we help you?</h2><label><Search/><input placeholder="Search help articles and guides..."/></label></Card><div className="adv-help-grid">{[[Plus,"Adding a Property",["How to create a new listing","Required property information","Saving and continuing a draft"]],[Home,"Managing Listings",["Understanding listing statuses","Editing a published listing","Making a property unavailable"]],[MessageCircle,"Enquiries & Inspections",["Responding to enquiries","Managing inspection requests","Recording calls and messages"]],[FolderOpen,"Documents & Verification",["Accepted identity documents","Uploading property documents","Why verification is required"]],[Settings,"Account & Security",["Updating account details","Changing contact preferences","Password and account security"]],[Sparkles,"TREL Services",["TREL managed sale or rental","Advertising-only listings","How TREL review works"]]].map(([Icon,h,links])=><Card key={h}><Icon/><h3>{h}</h3>{links.map(x=><button key={x}>{x}<ChevronRight/></button>)}<Link to="#">View all articles <ChevronRight/></Link></Card>)}</div><Card className="adv-support-card"><div><MessageCircle/><span><h3>Still need help?</h3><p>Our support team is available Monday to Friday, 8:00 AM–5:00 PM.</p></span></div><Button><MessageCircle/> Chat with Support</Button><Button secondary><Mail/> Email Support</Button><Button secondary><Phone/> Call +675 325 7900</Button></Card><Card><h3>Frequently Asked Questions</h3>{["How long does TREL review take?","Can I edit my listing after it is published?","Who can see my exact property location?","How many property photos can I upload?","What documents do I need to provide?"].map(x=><details key={x}><summary>{x}<ChevronDown/></summary><p>Open the relevant workspace section to review or update this information. Contact TREL support if you need further assistance.</p></details>)}</Card></>}

export default function AdvertiserWorkspace(){return <DraftProvider><AppShell><Routes><Route index element={<Dashboard/>}/><Route path="add-property" element={<PropertyDetails/>}/><Route path="add-property/location" element={<LocationPage/>}/><Route path="add-property/features" element={<FeaturesPage/>}/><Route path="add-property/photos" element={<PhotosPage/>}/><Route path="add-property/review" element={<ReviewPage/>}/><Route path="properties" element={<PropertiesPageFixed/>}/><Route path="enquiries" element={<EnquiriesPageFixed/>}/><Route path="inspections" element={<InspectionsPageFixed/>}/><Route path="documents" element={<DocumentsPageFixed/>}/><Route path="account-settings" element={<AccountSettingsFixed/>}/><Route path="activity" element={<ActivityPage/>}/><Route path="search" element={<SearchResultsPage/>}/><Route path="help" element={<HelpPage/>}/><Route path="*" element={<Navigate to="/advertiser" replace/>}/></Routes></AppShell></DraftProvider>}
